<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Falling Sand · Cellular Automata</title>
<style>
  :root{
    --bg:#0b0e14; --panel:#141925; --panel2:#1b2230;
    --ink:#e6edf6; --muted:#8a93a6; --accent:#5ad1ff;
    --sand:#e3b85a; --water:#3f8fe6; --wall:#7a7f8c; --acid:#9bff3c;
  }
  *{box-sizing:border-box}
  html,body{margin:0;height:100%}
  body{
    background:
      radial-gradient(1200px 600px at 50% -10%, #1a2336 0%, transparent 60%),
      var(--bg);
    color:var(--ink);
    font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    display:flex; flex-direction:column; align-items:center; justify-content:center;
    min-height:100vh; padding:24px; gap:16px;
  }
  h1{font-size:18px; letter-spacing:.18em; text-transform:uppercase; margin:0; color:#cfd8ea; font-weight:600}
  .stage{
    display:grid; grid-template-columns: 200px auto 200px; gap:20px; align-items:start;
    width:min(1000px,100%);
  }
  .panel{
    background:linear-gradient(180deg, var(--panel), var(--panel2));
    border:1px solid #243049; border-radius:14px; padding:14px;
    box-shadow: 0 10px 30px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.04);
  }
  .canvas-wrap{display:flex; flex-direction:column; align-items:center; gap:10px}
  #sand{
    display:block; width:600px; height:600px; max-width:78vw; max-height:78vw;
    background:#070a10; border:1px solid #243049; border-radius:10px;
    cursor:crosshair; touch-action:none;
    box-shadow: 0 0 0 1px rgba(255,255,255,.03), 0 20px 60px rgba(0,0,0,.5);
  }
  .controls{display:flex; flex-direction:column; gap:10px}
  .controls h2{font-size:11px; letter-spacing:.16em; text-transform:uppercase; color:var(--muted); margin:4px 2px}
  .mat-btn{
    display:flex; align-items:center; gap:10px;
    background:#101622; border:1px solid #2a3650; color:#cfd8ea;
    padding:10px 12px; border-radius:10px; cursor:pointer; font-size:14px;
    transition: transform .05s, background .15s, border-color .15s, box-shadow .15s;
  }
  .mat-btn .sw{width:16px;height:16px;border-radius:5px;border:1px solid rgba(0,0,0,.4)}
  .mat-btn:hover{background:#15203a}
  .mat-btn:active{transform:translateY(1px)}
  .mat-btn.active{border-color:var(--accent); box-shadow:0 0 0 2px rgba(90,209,255,.18) inset, 0 0 18px rgba(90,209,255,.15); background:#11203a}
  #clear{
    background:linear-gradient(180deg,#3a2230,#2a1722); border:1px solid #5a2a3c; color:#ffc2d4;
    padding:10px; border-radius:10px; cursor:pointer; font-size:13px; letter-spacing:.08em; text-transform:uppercase;
  }
  #clear:hover{background:linear-gradient(180deg,#4a2838,#3a1c28)}
  #clear:active{transform:translateY(1px)}
  .slider{display:flex; flex-direction:column; gap:6px}
  .slider label{font-size:11px; color:var(--muted); letter-spacing:.1em; text-transform:uppercase}
  input[type=range]{accent-color:var(--accent)}
  .right-col{display:flex; flex-direction:column; gap:10px}
  .stat{font-size:12px; color:var(--muted); display:flex; justify-content:space-between}
  .stat b{color:#cfd8ea; font-weight:600}
  .hint{font-size:12px; color:var(--muted); line-height:1.5}
  @media (max-width: 900px){
    .stage{grid-template-columns:1fr}
    .controls,.right-col{flex-direction:row; flex-wrap:wrap}
    .controls h2,.right-col h2{width:100%}
    #sand{width:92vw; height:92vw}
  }
</style>
</head>
<body>
  <h1>Falling Sand · Cellular Automata</h1>
  <div class="stage">
    <div class="panel controls">
      <h2>Material</h2>
      <button class="mat-btn active" id="mat-sand"><span class="sw" style="background:var(--sand)"></span>Sand</button>
      <button class="mat-btn" id="mat-water"><span class="sw" style="background:var(--water)"></span>Water</button>
      <button class="mat-btn" id="mat-wall"><span class="sw" style="background:var(--wall)"></span>Wall</button>
      <button class="mat-btn" id="mat-acid"><span class="sw" style="background:var(--acid)"></span>Acid</button>
      <button class="mat-btn" id="mat-empty"><span class="sw" style="background:#0c1119;border-color:#2a3650"></span>Eraser</button>
      <div class="slider" style="margin-top:6px">
        <label>Brush size · <span id="brushVal">3</span></label>
        <input type="range" id="brush" min="1" max="8" value="3">
      </div>
      <h2 style="margin-top:8px">Actions</h2>
      <button id="clear">Clear grid</button>
    </div>

    <div class="canvas-wrap">
      <canvas id="sand" width="600" height="600"></canvas>
    </div>

    <div class="panel right-col">
      <h2 style="font-size:11px; letter-spacing:.16em; text-transform:uppercase; color:var(--muted); margin:4px 2px">Status</h2>
      <div class="stat"><span>Cells</span><b id="stCells">0</b></div>
      <div class="stat"><span>Steps</span><b id="stSteps">0</b></div>
      <div class="stat"><span>Grid</span><b>100×100</b></div>
      <div class="stat"><span>Selected</span><b id="stMat">sand</b></div>
      <p class="hint">Drag to paint. Sand sinks through liquids; water spreads sideways; acid erodes walls and sand. Bottom-up stepping keeps every particle to one cell per step.</p>
    </div>
  </div>

<script>
(function(){
  "use strict";
  const W = 100, H = 100;
  const EMPTY=0, SAND=1, WATER=2, WALL=3, ACID=4;
  const NAMES = ["empty","sand","water","wall","acid"];
  const ID   = { empty:0, sand:1, water:2, wall:3, acid:4 };
  const BASE = [ null, [219,178,80], [55,128,220], [110,115,130], [155,255,60] ];

  const grid = new Uint8Array(W*H);
  const idx  = (x,y) => y*W + x;
  const inB  = (x,y) => x>=0 && x<W && y>=0 && y<H;

  let steps = 0;

  function get(x,y){ if(!inB(x,y)) return "wall"; return NAMES[grid[idx(x,y)]]; }
  function set(x,y,mat){
    if(!inB(x,y)) return;
    const id = ID[mat];
    if(id === undefined) return;
    grid[idx(x,y)] = id;
  }
  function clearGrid(){ grid.fill(0); steps = 0; }
  function countCells(){ let c=0; for(let i=0;i<grid.length;i++) if(grid[i]!==0) c++; return c; }

  const rint = n => (Math.random()*n)|0;

  // --- Sand: falls straight, swaps with water/acid (sinks), else slides diagonally ---
  function stepSand(x,y,i,moved){
    if(y+1 < H){
      const bi = idx(x,y+1), b = grid[bi];
      if(b === EMPTY){ grid[i]=EMPTY; grid[bi]=SAND; moved[bi]=1; return; }
      if(b === WATER || b === ACID){ grid[i]=b; grid[bi]=SAND; moved[bi]=1; return; }
    }
    const first = Math.random() < 0.5 ? 1 : -1;
    for(const d of [first, -first]){
      const nx = x + d;
      if(nx<0 || nx>=W || y+1>=H) continue;
      const ni = idx(nx,y+1), nb = grid[ni];
      if(nb === EMPTY){ grid[i]=EMPTY; grid[ni]=SAND; moved[ni]=1; return; }
      if(nb === WATER || nb === ACID){ grid[i]=nb; grid[ni]=SAND; moved[ni]=1; return; }
    }
  }

  // --- Water / Acid locomotion: fall, diagonal fall, then horizontal spread ---
  function stepLiquid(x,y,i,moved,mat){
    if(y+1 < H){
      const bi = idx(x,y+1), b = grid[bi];
      if(b === EMPTY){ grid[i]=EMPTY; grid[bi]=mat; moved[bi]=1; return; }
    }
    const first = Math.random() < 0.5 ? 1 : -1;
    for(const d of [first, -first]){
      const nx = x + d;
      if(nx<0 || nx>=W || y+1>=H) continue;
      const ni = idx(nx,y+1);
      if(grid[ni] === EMPTY){ grid[i]=EMPTY; grid[ni]=mat; moved[ni]=1; return; }
    }
    const hd = Math.random() < 0.5 ? 1 : -1;
    for(const d of [hd, -hd]){
      const nx = x + d;
      if(nx<0 || nx>=W) continue;
      const ni = idx(nx,y);
      if(grid[ni] === EMPTY){ grid[i]=EMPTY; grid[ni]=mat; moved[ni]=1; return; }
    }
  }

  // --- Acid: dissolve an adjacent sand/wall, then flow like a liquid ---
  function stepAcid(x,y,i,moved){
    const order = rint(4);
    const NB = [[0,1],[0,-1],[1,0],[-1,0]];
    for(let k=0;k<4;k++){
      const [dx,dy] = NB[(order+k)%4];
      const nx = x+dx, ny = y+dy;
      if(!inB(nx,ny)) continue;
      const ni = idx(nx,ny), nb = grid[ni];
      if(nb === SAND || nb === WALL){
        if(Math.random() < 0.10){
          grid[ni] = EMPTY; moved[ni] = 1;
          if(Math.random() < 0.55){ grid[i] = EMPTY; moved[i] = 1; return; } // acid consumed
        }
        break; // at most one dissolution attempt per tick
      }
    }
    stepLiquid(x,y,i,moved,ACID);
  }

  // --- One full simulation step (bottom-up, moved flags prevent double-move) ---
  function step(){
    const moved = new Uint8Array(W*H);
    for(let y = H-1; y >= 0; y--){
      for(let x = 0; x < W; x++){
        const i = idx(x,y);
        if(moved[i]) continue;
        const m = grid[i];
        if(m === EMPTY || m === WALL) continue;
        if(m === SAND) stepSand(x,y,i,moved);
        else if(m === WATER) stepLiquid(x,y,i,moved,WATER);
        else if(m === ACID) stepAcid(x,y,i,moved);
      }
    }
    steps++;
  }

  function tick(n){
    n = Math.max(0, Math.floor(n));
    for(let k=0; k<n; k++) step();
  }

  window.sim = { w:W, h:H, get, set, clear:clearGrid, tick, countCells };

  // ---------- Rendering ----------
  const canvas = document.getElementById('sand');
  const ctx = canvas.getContext('2d');
  const DPR = Math.min(2, window.devicePixelRatio || 1);
  function fit(){
    const cssW = canvas.clientWidth, cssH = canvas.clientHeight;
    canvas.width  = Math.round(cssW * DPR);
    canvas.height = Math.round(cssH * DPR);
  }
  fit();
  window.addEventListener('resize', fit);

  function colorFor(m,x,y){
    const base = BASE[m];
    let h = ((x*73856093) ^ (y*19349663) ^ ((m*2654435761)|0)) >>> 0;
    h = (h ^ (h >>> 13)) >>> 0;
    const j = ((h % 14) - 7) | 0;
    const r = Math.max(0, Math.min(255, base[0] + j));
    const g = Math.max(0, Math.min(255, base[1] + j));
    const b = Math.max(0, Math.min(255, base[2] + j));
    return `rgb(${r},${g},${b})`;
  }

  function render(){
    const cs = canvas.width / W;
    ctx.fillStyle = "#070a10";
    ctx.fillRect(0,0,canvas.width,canvas.height);
    for(let y=0;y<H;y++){
      for(let x=0;x<W;x++){
        const m = grid[idx(x,y)];
        if(m === EMPTY) continue;
        ctx.fillStyle = colorFor(m,x,y);
        ctx.fillRect(x*cs, y*cs, cs+0.6, cs+0.6);
      }
    }
  }

  // ---------- Animation loop (independent of tick) ----------
  let acc = 0, last = performance.now();
  function loop(t){
    const dt = Math.min(100, t - last); last = t;
    acc += dt;
    const sp = 1000/30; let n = 0;
    while(acc >= sp && n < 10){ step(); acc -= sp; n++; }
    render();
    stCells.textContent = countCells();
    stSteps.textContent = steps;
    requestAnimationFrame(loop);
  }

  // ---------- UI wiring ----------
  let current = SAND;
  const stMat   = document.getElementById('stMat');
  const stCells = document.getElementById('stCells');
  const stSteps = document.getElementById('stSteps');

  function select(id, name, btnId){
    current = id; stMat.textContent = name;
    document.querySelectorAll('.mat-btn').forEach(b => b.classList.remove('active'));
    document.getElementById(btnId).classList.add('active');
  }
  document.getElementById('mat-sand').onclick  = () => select(SAND,  'sand',  'mat-sand');
  document.getElementById('mat-water').onclick = () => select(WATER, 'water', 'mat-water');
  document.getElementById('mat-wall').onclick  = () => select(WALL,  'wall',  'mat-wall');
  document.getElementById('mat-acid').onclick  = () => select(ACID,  'acid',  'mat-acid');
  document.getElementById('mat-empty').onclick= () => select(EMPTY, 'empty', 'mat-empty');
  document.getElementById('clear').onclick = () => { clearGrid(); };

  const brush = document.getElementById('brush');
  const brushVal = document.getElementById('brushVal');
  brush.oninput = () => brushVal.textContent = brush.value;
  const brushR = () => parseInt(brush.value, 10);

  // ---------- Painting ----------
  function cellFromEvent(e){
    const rect = canvas.getBoundingClientRect();
    const cx = (e.clientX - rect.left) / rect.width  * W;
    const cy = (e.clientY - rect.top)  / rect.height * H;
    return { x: Math.floor(cx), y: Math.floor(cy) };
  }
  function paintAt(x,y){
    const r = brushR();
    for(let dy=-r; dy<=r; dy++){
      for(let dx=-r; dx<=r; dx++){
        if(dx*dx + dy*dy > r*r + 0.3) continue;
        const px = x+dx, py = y+dy;
        if(!inB(px,py)) continue;
        grid[idx(px,py)] = current;
      }
    }
  }
  function paintLine(x0,y0,x1,y1){
    const dx = x1-x0, dy = y1-y0;
    const n = Math.max(1, Math.abs(dx), Math.abs(dy));
    for(let i=0;i<=n;i++){
      paintAt(Math.round(x0 + dx*i/n), Math.round(y0 + dy*i/n));
    }
  }

  let painting = false, lastCell = null;
  function down(e){
    e.preventDefault(); painting = true;
    const c = cellFromEvent(e); paintAt(c.x,c.y); lastCell = c;
  }
  function move(e){
    if(!painting) return;
    e.preventDefault();
    const c = cellFromEvent(e);
    if(lastCell) paintLine(lastCell.x,lastCell.y,c.x,c.y); else paintAt(c.x,c.y);
    lastCell = c;
  }
  function up(){ painting = false; lastCell = null; }

  canvas.addEventListener('mousedown', down);
  window.addEventListener('mousemove', move);
  window.addEventListener('mouseup', up);
  canvas.addEventListener('touchstart', e => {
    const t = e.touches[0];
    down({ clientX:t.clientX, clientY:t.clientY, preventDefault:()=>e.preventDefault() });
  }, { passive:false });
  canvas.addEventListener('touchmove', e => {
    const t = e.touches[0];
    move({ clientX:t.clientX, clientY:t.clientY, preventDefault:()=>e.preventDefault() });
  }, { passive:false });
  canvas.addEventListener('touchend', up);

  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
